package com.fileapex.domain.clipboard

import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class SensitiveClipPolicyTest {
    @Test
    fun passwordManagerMarkersOnEveryPlatformAreSensitive() {
        listOf(
            "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
            "com.agilebits.onepassword", "x-kde-passwordManagerHint", "ExcludeClipboardContentFromMonitorProcessing",
            "Clipboard Viewer Ignore"
        ).forEach { marker ->
            assertTrue(marker, SensitiveClipPolicy.hasSensitiveMarker(listOf("public.utf8-plain-text", marker)))
        }
    }

    @Test
    fun markerNamesAreMatchedWithoutCaseOrSurroundingSpace() {
        assertTrue(SensitiveClipPolicy.hasSensitiveMarker(listOf("  ORG.NSPASTEBOARD.CONCEALEDTYPE\n")))
        assertTrue(SensitiveClipPolicy.hasSensitiveMarker(listOf("X-KDE-PASSWORDMANAGERHINT")))
    }

    @Test
    fun ordinaryFormatsAreNotSensitive() {
        assertFalse(SensitiveClipPolicy.hasSensitiveMarker(listOf("public.utf8-plain-text", "text/plain", "UTF8_STRING", "TARGETS")))
        assertFalse(SensitiveClipPolicy.hasSensitiveMarker(emptyList()))
    }

    @Test
    fun windowsHistoryFlagZeroMeansSensitiveAndOneOrMissingDoesNot() {
        assertTrue(SensitiveClipPolicy.windowsHistoryExcluded(0))
        assertFalse(SensitiveClipPolicy.windowsHistoryExcluded(1))
        assertFalse(SensitiveClipPolicy.windowsHistoryExcluded(null))
    }

    @Test
    fun oneTimeCodesAreRecognised() {
        listOf(
            "482913", "123 456", "123-456", "  482913\n", "Your code is 48291375",
            "Your verification code is 482913", "Verification code: 123 456", "Your code is 4829",
            "G-482913 is your Google verification code", "OTP 553201", "Tu código es 482913", "您的验证码：482913"
        ).forEach { assertTrue(it, SensitiveClipPolicy.looksLikeOneTimeCode(it)) }
    }

    @Test
    fun ordinaryTextIsNotAOneTimeCode() {
        listOf(
            "", "12", "123", "4829", "12345", "48291375", "123456789", "call me at 555 1234", "code review 2024", "see you at 18:30",
            "version 2.1.4", "https://example.com/482913", "hello world", "12345678901234567890", "\$12.99", "2026-11-14", "zip 90210"
        ).forEach { assertFalse(it, SensitiveClipPolicy.looksLikeOneTimeCode(it)) }
    }

    @Test
    fun aLongTextOrOneOverTheByteBoundIsNeverAOneTimeCode() {
        assertFalse(SensitiveClipPolicy.looksLikeOneTimeCode("Your code is 482913 " + "x".repeat(300)))
        assertFalse(SensitiveClipPolicy.looksLikeOneTimeCode("482913" + " ".repeat(SensitiveClipPolicy.OTP_MAX_BYTES)))
    }

    @Test
    fun theMarkerReadNeverRunsOnTheCallingThread() {
        val caller = Thread.currentThread()
        var readOn: Thread? = null
        val blocked = kotlinx.coroutines.runBlocking {
            SensitiveClipPolicy.blocksAutomaticSend("meeting notes") {
                readOn = Thread.currentThread()
                false
            }
        }
        assertFalse(blocked)
        assertTrue("marker read ran on the caller", readOn != null && readOn !== caller)
    }

    @Test
    fun aMarkedClipIsBlockedAndACodeLikeClipDoesNotNeedThePlatformRead() {
        assertTrue(kotlinx.coroutines.runBlocking { SensitiveClipPolicy.blocksAutomaticSend("hunter2") { true } })
        var read = false
        assertTrue(kotlinx.coroutines.runBlocking { SensitiveClipPolicy.blocksAutomaticSend("Your code is 482913") { read = true; false } })
        assertFalse("platform read for a code-like clip", read)
    }
}

